insert into public.lesson_blocks (lesson_id, block_type, title, content, data, sort_order) values
('school-5b-num-01', 'objective', 'Meta de aprendizaje', 'Hoy vas a leer y construir números grandes sin miedo, entendiendo qué valor tiene cada cifra según el lugar donde está.', '{}'::jsonb, 1),
('school-5b-num-01', 'prerequisites', 'Lo que ya sabes', 'Activemos ideas que te ayudarán a avanzar.', '{"items": [{"icon": "🔟", "title": "Diez hace el siguiente grupo", "body": "10 unidades forman 1 decena, 10 decenas forman 1 centena y así sucesivamente."}, {"icon": "📖", "title": "Leer números", "body": "Es más fácil si separas el número en grupos de tres cifras."}, {"icon": "↔️", "title": "Comparar cantidades", "body": "Si dos números tienen distinta cantidad de cifras, el que tiene más cifras suele ser mayor."}]}'::jsonb, 2),
('school-5b-num-01', 'text', 'Una historia para comenzar', 'En una reserva natural registraron 245 901 semillas para reforestar. El guardaparque dijo: “¡Es un número grande, pero si lo separo en grupos lo puedo leer mejor!”. Eso mismo haremos aquí: mirar el número por partes para entenderlo.', '{"variant": "story", "emoji": "🌱"}'::jsonb, 3),
('school-5b-num-01', 'concepts', 'Puntos importantes', null, '{"items": [{"icon": "🏠", "title": "Valor posicional", "body": "El mismo dígito puede valer cosas distintas. En 245 901, el 2 vale doscientas mil unidades."}, {"icon": "🧱", "title": "Formar y descomponer", "body": "Un número puede expresarse como suma de valores: 245 901 = 200 000 + 40 000 + 5 000 + 900 + 1."}, {"icon": "📏", "title": "Comparar y ordenar", "body": "Compara primero la cantidad de cifras. Si es igual, observa de izquierda a derecha hasta encontrar una diferencia."}]}'::jsonb, 4),
('school-5b-num-01', 'math_model', 'Casa del valor posicional', 'Observa cómo el número se organiza en familias de tres cifras.', '{"mode": "place_value", "value": "245901", "caption": "Agrupar de tres en tres ayuda a leer y comprender números grandes."}'::jsonb, 5),
('school-5b-num-01', 'strategy', 'Cómo leer y comparar números grandes', 'Usa siempre la misma rutina para que no se te escape ninguna cifra.', '{"steps": [{"title": "Separa en grupos de tres", "body": "Por ejemplo: 245 | 901."}, {"title": "Lee cada grupo con su nombre", "body": "245 se lee doscientos cuarenta y cinco mil; 901 se lee novecientos uno."}, {"title": "Para comparar, mira de izquierda a derecha", "body": "Compara las cifras desde el lugar de mayor valor hasta encontrar cuál es mayor."}, {"title": "Comprueba con una descomposición", "body": "Si descompones, puedes explicar por qué un número es mayor que otro."}]}'::jsonb, 6),
('school-5b-num-01', 'examples', 'Ejemplos resueltos', null, '{"examples": [{"title": "Lectura y escritura", "problem": "¿Cómo se lee 318 042?", "strategy": "Lo separo como 318 | 042 y luego leo cada grupo.", "steps": ["318 corresponde al grupo de los miles.", "042 corresponde a 42 unidades.", "Entonces el número se lee trescientos dieciocho mil cuarenta y dos."], "answer": "318 042 se lee “trescientos dieciocho mil cuarenta y dos”.", "takeaway": "El cero puede ocupar un lugar sin cambiar el valor de las otras cifras."}, {"title": "Descomposición", "problem": "Descompón 507 230.", "strategy": "Miro cada cifra según su posición.", "steps": ["5 está en las centenas de mil, así que vale 500 000.", "7 está en las unidades de mil, así que vale 7 000.", "2 está en las centenas, así que vale 200.", "3 está en las decenas, así que vale 30."], "answer": "507 230 = 500 000 + 7 000 + 200 + 30", "takeaway": "También puedes omitir los valores cero en la descomposición."}, {"title": "Comparación", "problem": "Compara 425 901 y 418 999.", "strategy": "Ambos tienen 6 cifras, así que comparo de izquierda a derecha.", "steps": ["En las centenas de mil ambos tienen 4.", "En las decenas de mil, 2 es mayor que 1.", "Por eso ya no necesito seguir comparando."], "answer": "425 901 > 418 999", "verification": "Si los ubicas en una recta, 425 901 queda a la derecha."}]}'::jsonb, 7),
('school-5b-num-01', 'guided_practice', 'Ejercitación guiada', 'Ahora intenta tú, siguiendo las pistas.', '{"items": [{"title": "Lee y escribe", "problem": "Escribe en palabras el número 670 305.", "hints": ["Separa 670 | 305.", "Lee primero el grupo de los miles."], "answer": "Seiscientos setenta mil trescientos cinco."}, {"title": "Ordena", "problem": "Ordena de menor a mayor: 89 999, 90 001 y 90 010.", "hints": ["Observa la cantidad de cifras.", "Luego compara los números que comienzan con 90."], "answer": "89 999 < 90 001 < 90 010", "challenge": "Explica por qué 90 010 es mayor que 90 001."}]}'::jsonb, 8),
('school-5b-num-01', 'text', 'Detente y piensa', 'Si tuvieras que inventar un número de 6 cifras mayor que 320 000 y menor que 330 000, ¿qué condiciones debe cumplir?', '{"variant": "checkpoint", "prompts": ["¿Qué cifra puede estar en las centenas de mil?", "¿Qué pasa con las decenas de mil?", "Da un ejemplo y explícalo."]}'::jsonb, 9),
('school-5b-num-01', 'common_errors', 'Errores frecuentes', null, '{"items": [{"title": "Leer por cifras sueltas", "body": "No digas “dos, cuatro, cinco, nueve, cero, uno”. Lee el número por grupos y con su nombre completo."}, {"title": "Olvidar el valor del lugar", "body": "El 5 no siempre vale 5. En 507 230, ese 5 vale 500 000."}]}'::jsonb, 10),
('school-5b-num-01', 'tip', 'Trucos útiles', null, '{"items": ["Usa espacios o puntos como separadores de miles para ordenar tu vista.", "Si dudas, descompón el número: la descomposición te obliga a mirar cada posición."]}'::jsonb, 11),
('school-5b-num-01', 'summary', 'Lo esencial de esta lección', 'Qué debes recordar antes de practicar.', '{"items": ["Un número grande se entiende mejor cuando se separa en grupos de tres cifras.", "El valor de una cifra depende de su posición.", "Para comparar, se mira desde la cifra de mayor valor hacia la derecha."]}'::jsonb, 12),
('school-5b-num-01', 'practice', '¿Qué sigue ahora?', 'Pasa a la práctica del tema para consolidar la lectura, la escritura y la comparación de números grandes.', '{"items": ["Lee y escribe números grandes.", "Forma números a partir de descripciones.", "Compara y ordena usando valor posicional."]}'::jsonb, 13),
('school-5b-num-02', 'objective', 'Meta de aprendizaje', 'Hoy descubrirás que multiplicar mentalmente es más fácil cuando transformas el cálculo en otro que ya conoces.', '{}'::jsonb, 1),
('school-5b-num-02', 'prerequisites', 'Lo que ya sabes', 'Antes de empezar, recuerda estas ideas.', '{"items": [{"icon": "✖️", "title": "Tablas básicas", "body": "Conocer las tablas del 2, 5 y 10 ayuda mucho."}, {"icon": "🔁", "title": "Doblar y partir por la mitad", "body": "A veces puedes duplicar un factor y dividir el otro por 2."}, {"icon": "🧮", "title": "Descomponer", "body": "Puedes separar 24 en 20 + 4 para calcular más cómodamente."}]}'::jsonb, 2),
('school-5b-num-02', 'text', 'Multiplicar sin lápiz', 'En la feria, una profesora compró 6 bolsas con 30 naranjas cada una. Antes de pagar, quiso saber rápido cuántas naranjas llevaba. No hizo el algoritmo: pensó 6 × 3 decenas = 18 decenas = 180.', '{"variant": "story", "emoji": "🍊"}'::jsonb, 3),
('school-5b-num-02', 'concepts', 'Ideas clave', null, '{"items": [{"icon": "🎯", "title": "Multiplicar por 10, 20 o 30", "body": "Primero multiplica por 1, 2 o 3 y luego agrega el valor de las decenas."}, {"icon": "🪄", "title": "Propiedad distributiva", "body": "24 × 6 puede pensarse como (20 × 6) + (4 × 6)."}, {"icon": "⚖️", "title": "Dobles y mitades", "body": "16 × 25 puede verse como 8 × 50 o 4 × 100."}]}'::jsonb, 4),
('school-5b-num-02', 'math_model', 'Arreglo rectangular', 'Cada fila representa un grupo igual. Contar por filas o por columnas da el mismo total.', '{"mode": "multiplication_array", "rows": 4, "cols": 6, "caption": "Los arreglos ayudan a ver la multiplicación como grupos iguales."}'::jsonb, 5),
('school-5b-num-02', 'strategy', 'Estrategias que te ahorran tiempo', 'Elige la estrategia que te deje un cálculo más cómodo.', '{"steps": [{"title": "Busca múltiplos de 10", "body": "Por ejemplo, 7 × 30 = 7 × 3 decenas = 21 decenas = 210."}, {"title": "Descompón el número difícil", "body": "23 × 4 = (20 × 4) + (3 × 4)."}, {"title": "Usa dobles o mitades", "body": "8 × 25 puede transformarse en 4 × 50 y luego en 2 × 100."}]}'::jsonb, 6),
('school-5b-num-02', 'examples', 'Ejemplos resueltos', null, '{"examples": [{"problem": "Calcula 7 × 40.", "strategy": "Pienso 7 × 4 y luego considero que 40 son 4 decenas.", "steps": ["7 × 4 = 28.", "28 decenas = 280."], "answer": "7 × 40 = 280"}, {"problem": "Calcula 18 × 5 mentalmente.", "strategy": "Descompongo 18 en 10 y 8.", "steps": ["10 × 5 = 50.", "8 × 5 = 40.", "50 + 40 = 90."], "answer": "18 × 5 = 90", "takeaway": "Descomponer funciona muy bien cuando uno de los factores es pequeño."}, {"problem": "Calcula 16 × 25.", "strategy": "Hago dobles y mitades.", "steps": ["16 × 25 = 8 × 50.", "8 × 50 = 4 × 100.", "4 × 100 = 400."], "answer": "16 × 25 = 400", "verification": "También puedes comprobar con 25 + 25 + ... 16 veces, pero sería más largo."}]}'::jsonb, 7),
('school-5b-num-02', 'guided_practice', 'Ejercitación guiada', 'Piensa qué estrategia conviene más en cada caso.', '{"items": [{"problem": "Calcula 9 × 30.", "hints": ["Primero 9 × 3.", "Luego cambia ese resultado a decenas."], "answer": "270"}, {"problem": "Calcula 24 × 5.", "hints": ["Puedes descomponer 24 o pensar en la mitad de 24 × 10."], "answer": "120", "challenge": "Explica dos formas distintas de obtener el mismo resultado."}]}'::jsonb, 8),
('school-5b-num-02', 'text', 'Piensa antes de calcular', '¿Cuál de estas multiplicaciones resolverías con dobles y mitades: 14 × 50, 17 × 6 o 39 × 4? ¿Por qué?', '{"variant": "checkpoint", "prompts": ["¿Cuál te deja una multiplicación más simple?", "¿Qué cálculo nuevo obtienes?"]}'::jsonb, 9),
('school-5b-num-02', 'common_errors', 'Errores frecuentes', null, '{"items": [{"title": "Olvidar el valor de las decenas", "body": "En 7 × 40, no basta con decir 28. Debes pensar 28 decenas = 280."}, {"title": "Descomponer y olvidar sumar", "body": "Si haces 24 × 6 = 20 × 6 y 4 × 6, al final debes juntar ambos productos."}]}'::jsonb, 10),
('school-5b-num-02', 'tip', 'Trucos útiles', null, '{"items": ["Si ves un 25, piensa en 100 ÷ 4.", "Si ves un 50, piensa en 100 ÷ 2.", "Si uno de los factores es 5, también puedes multiplicar por 10 y tomar la mitad."]}'::jsonb, 11),
('school-5b-num-02', 'summary', 'Lo esencial de esta lección', 'El cálculo mental se vuelve más seguro cuando eliges una estrategia.', '{"items": ["Multiplicar por 20 o 30 es multiplicar por 2 o 3 decenas.", "Descomponer te permite usar cálculos más fáciles.", "Dobles y mitades pueden convertir una multiplicación complicada en otra más cómoda."]}'::jsonb, 12),
('school-5b-num-02', 'practice', '¿Qué sigue ahora?', 'Continúa con la práctica para dominar estrategias de multiplicación mental.', '{"items": ["Múltiplos de 10.", "Descomposición.", "Dobles y mitades."]}'::jsonb, 13),
('school-5b-num-03', 'objective', 'Meta de aprendizaje', 'Aprenderás a multiplicar números de dos dígitos usando estimación, productos parciales y algoritmo.', '{}'::jsonb, 1),
('school-5b-num-03', 'prerequisites', 'Lo que ya sabes', 'Estas ideas te servirán mucho.', '{"items": [{"icon": "🧱", "title": "Descomponer en decenas y unidades", "body": "34 = 30 + 4."}, {"icon": "🎯", "title": "Estimar", "body": "Antes de calcular, puedes aproximar para saber si tu respuesta será razonable."}, {"icon": "✖️", "title": "Hechos básicos", "body": "Necesitarás las tablas de multiplicar con seguridad."}]}'::jsonb, 2),
('school-5b-num-03', 'text', 'Antes de usar el algoritmo', 'Cuando Matías quiere calcular 23 × 14, primero piensa si el resultado será cercano a 200, 300 o 500. Así puede revisar luego si el algoritmo quedó bien.', '{"variant": "story", "emoji": "🧠"}'::jsonb, 3),
('school-5b-num-03', 'concepts', 'Puntos importantes', null, '{"items": [{"icon": "📦", "title": "Productos parciales", "body": "23 × 14 significa 23 × (10 + 4), por eso se calculan dos productos y luego se suman."}, {"icon": "🧭", "title": "Estimación", "body": "23 × 14 es cercano a 20 × 10 = 200 o 25 × 15 = 375; el resultado exacto debe ser razonable."}, {"icon": "🧾", "title": "Algoritmo con sentido", "body": "Cada fila del algoritmo representa un producto parcial."}]}'::jsonb, 4),
('school-5b-num-03', 'math_model', 'Arreglo de productos parciales', 'El rectángulo se puede desarmar en partes más simples.', '{"mode": "multiplication_array", "rows": 12, "cols": 4, "caption": "Piensa que una multiplicación grande puede dividirse en arreglos más pequeños."}'::jsonb, 5),
('school-5b-num-03', 'strategy', 'Cómo resolver una multiplicación de dos dígitos', 'Sigue este camino.', '{"steps": [{"title": "Estima el resultado", "body": "Así sabrás si tu respuesta final tiene sentido."}, {"title": "Descompón el segundo factor", "body": "Por ejemplo, 14 = 10 + 4."}, {"title": "Calcula los productos parciales", "body": "23 × 10 y 23 × 4."}, {"title": "Suma los resultados", "body": "El total de ambos productos parciales da el producto exacto."}]}'::jsonb, 6),
('school-5b-num-03', 'examples', 'Ejemplos resueltos', null, '{"examples": [{"problem": "Calcula 23 × 14 usando productos parciales.", "strategy": "Descompongo 14 en 10 y 4.", "steps": ["23 × 10 = 230.", "23 × 4 = 92.", "230 + 92 = 322."], "answer": "23 × 14 = 322", "verification": "La estimación 20 × 15 = 300 muestra que 322 es razonable."}, {"problem": "Calcula 36 × 27.", "strategy": "Descompongo 27 en 20 y 7.", "steps": ["36 × 20 = 720.", "36 × 7 = 252.", "720 + 252 = 972."], "answer": "36 × 27 = 972"}, {"problem": "Usa el algoritmo para 48 × 12.", "strategy": "Recuerda que la segunda fila representa decenas.", "steps": ["48 × 2 = 96.", "48 × 10 = 480.", "96 + 480 = 576."], "answer": "48 × 12 = 576", "takeaway": "El cero del 10 no siempre se escribe si entiendes que la segunda fila representa decenas."}]}'::jsonb, 7),
('school-5b-num-03', 'guided_practice', 'Ejercitación guiada', 'Haz primero una estimación y luego resuelve.', '{"items": [{"problem": "Calcula 32 × 15.", "hints": ["Descompón 15 en 10 y 5.", "Suma los productos parciales."], "answer": "480"}, {"problem": "Calcula 41 × 18.", "hints": ["Puedes pensar 18 = 20 - 2 o 10 + 8.", "Elige la forma que te resulte más clara."], "answer": "738"}]}'::jsonb, 8),
('school-5b-num-03', 'text', 'Comprueba tu respuesta', 'Si 32 × 15 te dio 48, ¿qué pista te da la estimación para darte cuenta del error?', '{"variant": "checkpoint", "prompts": ["¿Es posible que 32 grupos de 15 den menos de 100?", "¿Qué estimación rápida harías?"]}'::jsonb, 9),
('school-5b-num-03', 'common_errors', 'Errores frecuentes', null, '{"items": [{"title": "Olvidar que una fila representa decenas", "body": "En el algoritmo, al multiplicar por la decena estás calculando decenas completas, no unidades."}, {"title": "Sumar mal los productos parciales", "body": "A veces el cálculo de cada parte está bien, pero el error aparece al juntar los resultados."}]}'::jsonb, 10),
('school-5b-num-03', 'tip', 'Trucos útiles', null, '{"items": ["Estima antes y después de resolver.", "Si el resultado es muy distinto de la estimación, revisa el cálculo."]}'::jsonb, 11),
('school-5b-num-03', 'summary', 'Lo esencial de esta lección', 'Qué conviene recordar.', '{"items": ["Multiplicar por dos dígitos es sumar productos parciales.", "La estimación te ayuda a revisar si el producto exacto es razonable.", "El algoritmo tiene sentido cuando entiendes qué representa cada fila."]}'::jsonb, 12),
('school-5b-num-03', 'practice', '¿Qué sigue ahora?', 'Practica multiplicaciones de dos dígitos con productos parciales y algoritmo.', '{"items": ["Estimación.", "Productos parciales.", "Algoritmo."]}'::jsonb, 13),
('school-5b-num-04', 'objective', 'Meta de aprendizaje', 'Aprenderás a dividir pensando en grupos o repartos, y a decidir qué hacer con el resto.', '{}'::jsonb, 1),
('school-5b-num-04', 'prerequisites', 'Lo que ya sabes', 'Necesitarás estas ideas.', '{"items": [{"icon": "➕", "title": "Repartir y agrupar", "body": "Dividir puede significar repartir en partes iguales o formar grupos iguales."}, {"icon": "✖️", "title": "Relación con la multiplicación", "body": "Si 6 × 4 = 24, entonces 24 ÷ 6 = 4 y 24 ÷ 4 = 6."}, {"icon": "🔍", "title": "Resto", "body": "No siempre todo alcanza para formar grupos completos."}]}'::jsonb, 2),
('school-5b-num-04', 'text', '¿Qué significa el resto?', 'Una profesora tiene 26 lápices y quiere guardarlos en cajas de 4. Puede llenar 6 cajas y le sobran 2 lápices. En algunos problemas el resto se conserva; en otros, obliga a sumar un grupo más.', '{"variant": "story", "emoji": "✏️"}'::jsonb, 3),
('school-5b-num-04', 'concepts', 'Ideas clave', null, '{"items": [{"icon": "👥", "title": "Reparto", "body": "Se conoce la cantidad de grupos y se quiere saber cuánto toca en cada uno."}, {"icon": "🧺", "title": "Agrupamiento", "body": "Se conoce el tamaño del grupo y se quiere saber cuántos grupos se forman."}, {"icon": "🧠", "title": "Interpretar el resto", "body": "El resto no siempre se escribe igual en la respuesta final; depende del contexto."}]}'::jsonb, 4),
('school-5b-num-04', 'math_model', 'Grupos iguales', 'La división puede verse como formar grupos del mismo tamaño.', '{"mode": "division_groups", "total": 26, "group_size": 4, "caption": "Se forman 6 grupos completos de 4 y sobran 2."}'::jsonb, 5),
('school-5b-num-04', 'strategy', 'Cómo enfrentar una división', 'Piensa antes de ejecutar el algoritmo.', '{"steps": [{"title": "Decide si es reparto o agrupamiento", "body": "Eso te ayuda a interpretar el resultado."}, {"title": "Busca un cálculo cercano", "body": "Por ejemplo, para 86 ÷ 4 piensa en múltiplos de 4 cercanos a 86."}, {"title": "Aplica el algoritmo si lo necesitas", "body": "Avanza de izquierda a derecha y registra el resto parcial."}, {"title": "Interpreta el resto con palabras", "body": "Pregunta: ¿sobra?, ¿falta un grupo?, ¿se puede repartir en partes?"}]}'::jsonb, 6),
('school-5b-num-04', 'examples', 'Ejemplos resueltos', null, '{"examples": [{"problem": "26 lápices se guardan en cajas de 4. ¿Cuántas cajas se llenan y cuántos lápices sobran?", "strategy": "Es un agrupamiento.", "steps": ["Busco múltiplos de 4 cercanos a 26.", "4 × 6 = 24.", "Sobran 2 lápices."], "answer": "Se llenan 6 cajas y sobran 2 lápices."}, {"problem": "84 galletas se reparten entre 7 niños. ¿Cuántas recibe cada uno?", "strategy": "Es un reparto exacto.", "steps": ["84 ÷ 7 = 12.", "No sobra nada."], "answer": "Cada niño recibe 12 galletas."}, {"problem": "Se necesitan viajes de 9 personas para trasladar a 41 estudiantes. ¿Cuántos viajes se requieren?", "strategy": "Aunque sobre un resto, igual hace falta otro viaje.", "steps": ["41 ÷ 9 = 4 y sobran 5.", "Con 4 viajes viajan 36 estudiantes.", "Quedan 5, así que se necesita un viaje adicional."], "answer": "Se requieren 5 viajes.", "takeaway": "A veces el resto obliga a redondear hacia arriba en la respuesta final."}]}'::jsonb, 7),
('school-5b-num-04', 'guided_practice', 'Ejercitación guiada', 'Resuelve y luego interpreta el resto.', '{"items": [{"problem": "37 flores se agrupan de 5 en 5. ¿Cuántos ramos completos se forman y cuántas flores sobran?", "hints": ["Busca el múltiplo de 5 más cercano sin pasarte."], "answer": "7 ramos completos y sobran 2 flores."}, {"problem": "Hay 52 asientos y van 8 estudiantes por fila. ¿Cuántas filas completas se llenan?", "hints": ["Piensa en 8 × 6 y 8 × 7."], "answer": "6 filas completas y sobran 4 asientos."}]}'::jsonb, 8),
('school-5b-num-04', 'text', 'Detente y razona', 'En un problema, 31 ÷ 6 = 5 y sobra 1. ¿Cuándo responderías 5, cuándo 5 y sobra 1, y cuándo 6?', '{"variant": "checkpoint", "prompts": ["Inventa un contexto para cada respuesta."]}'::jsonb, 9),
('school-5b-num-04', 'common_errors', 'Errores frecuentes', null, '{"items": [{"title": "Olvidar interpretar el resto", "body": "El algoritmo entrega un número y un resto, pero el problema te pide una respuesta con sentido."}, {"title": "Confundir reparto con agrupamiento", "body": "Ambas situaciones usan división, pero las preguntas que responden son distintas."}]}'::jsonb, 10),
('school-5b-num-04', 'tip', 'Trucos útiles', null, '{"items": ["Comprueba una división con multiplicación: divisor × cociente + resto = dividendo.", "Si el contexto habla de buses, cajas o viajes, piensa si el resto obliga a sumar uno más."]}'::jsonb, 11),
('school-5b-num-04', 'summary', 'Lo esencial de esta lección', 'Qué debes llevarte.', '{"items": ["Dividir puede significar repartir o agrupar.", "El resto siempre se interpreta con el contexto.", "La comprobación con multiplicación ayuda a revisar el resultado."]}'::jsonb, 12),
('school-5b-num-04', 'practice', '¿Qué sigue ahora?', 'Pasa a la práctica para consolidar la división y la interpretación del resto.', '{"items": ["Repartos exactos.", "Agrupamientos con resto.", "Problemas en contexto."]}'::jsonb, 13),
('school-5b-oa-19', 'objective', 'Meta de aprendizaje', 'Aprenderás a medir mejor, elegir una buena unidad y explicar por qué la elegiste.', '{}'::jsonb, 1),
('school-5b-oa-19', 'prerequisites', 'Lo que ya sabes', 'Recordemos algunas ideas.', '{"items": [{"icon": "📏", "title": "Medir es comparar", "body": "Medir una longitud es compararla con una unidad."}, {"icon": "🔹", "title": "Unidades de longitud", "body": "mm, cm, m y km sirven para situaciones distintas."}, {"icon": "👀", "title": "Estimar", "body": "Antes de medir, una estimación te ayuda a revisar si el resultado tiene sentido."}]}'::jsonb, 2),
('school-5b-oa-19', 'text', '¿Qué unidad conviene?', 'No usarías kilómetros para medir un lápiz ni milímetros para indicar la distancia entre dos ciudades. Una buena parte de medir consiste en elegir bien la unidad.', '{"variant": "story", "emoji": "📐"}'::jsonb, 3),
('school-5b-oa-19', 'concepts', 'Puntos importantes', null, '{"items": [{"icon": "🪶", "title": "Objetos pequeños", "body": "Para grosores o detalles muy pequeños suele convenir el milímetro."}, {"icon": "✏️", "title": "Objetos cotidianos", "body": "Un lápiz, un cuaderno o una mesa suelen medirse en centímetros."}, {"icon": "🚪", "title": "Espacios grandes", "body": "Puertas, piezas o patios pueden expresarse mejor en metros."}]}'::jsonb, 4),
('school-5b-oa-19', 'math_model', 'Regla graduada', 'Mira cómo se ubican las marcas en una recta de medida.', '{"mode": "ruler", "start": 0, "end": 10, "step": 1, "highlight": 6, "caption": "La marca destacada se ubica en 6 unidades de la escala."}'::jsonb, 5),
